do

local BeginTextCommandThefeedPost, EndTextCommandThefeedPostTicker = BeginTextCommandThefeedPost, EndTextCommandThefeedPostTicker
local ThefeedSetNextPostBackgroundColor = ThefeedSetNextPostBackgroundColor
local EndTextCommandThefeedPostMessagetext = EndTextCommandThefeedPostMessagetext
local AddTextComponentSubstringPlayerName = AddTextComponentSubstringPlayerName
local BeginTextCommandDisplayHelp, EndTextCommandDisplayHelp = BeginTextCommandDisplayHelp, EndTextCommandDisplayHelp
local BeginTextCommandPrint, EndTextCommandPrint, ClearPrints = BeginTextCommandPrint, EndTextCommandPrint, ClearPrints
local SetTextScale, SetTextFont, SetTextColour, SetTextDropShadow, SetTextOutline, SetTextCentre =
  SetTextScale, SetTextFont, SetTextColour, SetTextDropShadow, SetTextOutline, SetTextCentre
local BeginTextCommandDisplayText, EndTextCommandDisplayText = BeginTextCommandDisplayText, EndTextCommandDisplayText
local SetDrawOrigin, ClearDrawOrigin = SetDrawOrigin, ClearDrawOrigin
local tostring, byte, sub = tostring, string.byte, string.sub

-- A text component holds at most 99 bytes: longer texts use the CELL_EMAIL_BCON label, made of ten ~a~
-- placeholders, so at most 10 chunks are rendered.
local MAX_CHUNK = 99
local MAX_CHUNKS = 10
local LONG_LABEL = "CELL_EMAIL_BCON"

---@param text string
---@return string label
local function labelFor(text)
  return #text <= MAX_CHUNK and "STRING" or LONG_LABEL
end
---@param text string
local function addText(text)
  local len = #text
  if len <= MAX_CHUNK then AddTextComponentSubstringPlayerName(text); return end
  local i, n = 1, 0
  while i <= len do
    n = n + 1
    if n > MAX_CHUNKS then
      if fx.debug then
        Citizen.Trace(("^3[fx] text truncated: %d bytes, only %d chunks of %d bytes are rendered^7\n"):format(len, MAX_CHUNKS, MAX_CHUNK))
      end
      return
    end
    local j = i + MAX_CHUNK - 1
    if j < len then
      -- do not cut a UTF-8 sequence: back off over continuation bytes
      while j > i and (byte(text, j + 1) or 0) & 0xC0 == 0x80 do j = j - 1 end
    end
    AddTextComponentSubstringPlayerName(sub(text, i, j))
    i = j + 1
  end
end
rt.addText, rt.textLabel = addText, labelFor

---@param text any
---@param opts? fx.NotifyOptions
---@return integer notificationId
statics.notify = function(text, opts)
  text = tostring(text)
  if opts and opts.background then ThefeedSetNextPostBackgroundColor(opts.background) end
  BeginTextCommandThefeedPost(labelFor(text))
  addText(text)
  local p = opts and opts.picture
  if p then
    EndTextCommandThefeedPostMessagetext(p.dict, p.name or p.dict, false, p.icon or 0, p.sender or "", p.subject or "")
  end
  return EndTextCommandThefeedPostTicker(opts and opts.important or false, true)
end

---@param text any
---@param duration? integer
---@param opts? { beep?: boolean, loop?: boolean }
statics.help = function(text, duration, opts)
  text = tostring(text)
  BeginTextCommandDisplayHelp(labelFor(text))
  addText(text)
  EndTextCommandDisplayHelp(0, opts and opts.loop or false, opts and opts.beep or false, duration or -1)
end

---@param text any
---@param duration? integer
statics.subtitle = function(text, duration)
  text = tostring(text)
  ClearPrints()
  BeginTextCommandPrint(labelFor(text))
  addText(text)
  EndTextCommandPrint(duration or 2500, true)
end

---@param opts? fx.TextOptions
local function textStyle(opts)
  local scale = opts and opts.scale or 0.35
  SetTextScale(0.0, scale + 0.0)
  SetTextFont(opts and opts.font or 4)
  local c = opts and opts.color
  if c then SetTextColour(c[1] or c.r, c[2] or c.g, c[3] or c.b, c[4] or c.a or 255)
  else SetTextColour(255, 255, 255, 255) end
  if not (opts and opts.shadow == false) then SetTextDropShadow() end
  if opts and opts.outline then SetTextOutline() end
  SetTextCentre(not (opts and opts.centre == false))
end

---@param text any
---@param x number
---@param y number
---@param opts? fx.TextOptions
statics.drawText = function(text, x, y, opts)
  text = tostring(text)
  textStyle(opts)
  BeginTextCommandDisplayText(labelFor(text))
  addText(text)
  EndTextCommandDisplayText(x + 0.0, y + 0.0)
end

---@param text any
---@param position vector3
---@param opts? fx.TextOptions
statics.drawText3d = function(text, position, opts)
  text = tostring(text)
  SetDrawOrigin(position.x + 0.0, position.y + 0.0, position.z + 0.0, 0)
  textStyle(opts)
  BeginTextCommandDisplayText(labelFor(text))
  addText(text)
  EndTextCommandDisplayText(0.0, 0.0)
  ClearDrawOrigin()
end

local RequestAdditionalText, HasThisAdditionalTextLoaded = RequestAdditionalText, HasThisAdditionalTextLoaded

---@param gxt any
---@param slot any
---@return boolean
local function validText(gxt, slot) return type(gxt) == "string" and gxt ~= "" and math.type(slot) == "integer" end

---@param gxt string
---@param slot integer
---@param timeoutMs? integer
---@return fx.Promise<string>
statics.loadAdditionalTextAsync = function(gxt, slot, timeoutMs)
  return rt.load("Hud.loadAdditionalTextAsync", "text block or slot", RequestAdditionalText, HasThisAdditionalTextLoaded,
    validText, timeoutMs, gxt, slot)
end

local IsWaypointActive, GetFirstBlipInfoId, GetBlipInfoIdCoord = IsWaypointActive, GetFirstBlipInfoId, GetBlipInfoIdCoord
local SetNewWaypoint, SetWaypointOff = SetNewWaypoint, SetWaypointOff
-- blip sprite 8 = the waypoint
local WAYPOINT_SPRITE = 8

---@return vector3?
staticGetters.waypoint = function()
  local active = IsWaypointActive()
  if active ~= true and active ~= 1 then return nil end
  local blip = GetFirstBlipInfoId(WAYPOINT_SPRITE)
  if not blip or blip == 0 then return nil end
  return GetBlipInfoIdCoord(blip)
end

---@param v vector2|vector3|nil
staticSetters.waypoint = function(v)
  if v == nil then SetWaypointOff(); return end
  local t = type(v)
  if t ~= "vector3" and t ~= "vector2" then error("Hud.waypoint: expected a vector2, a vector3 or nil, got " .. t, 3) end
  SetNewWaypoint(v.x + 0.0, v.y + 0.0)
end

local DisplayRadar, DisplayHud, SetBigmapActive, SetRadarZoom = DisplayRadar, DisplayHud, SetBigmapActive, SetRadarZoom
local IsRadarHidden, IsHudHidden = rt.bool(IsRadarHidden), rt.bool(IsHudHidden)
local IsBigmapActive, IsBigmapFull = rt.bool(IsBigmapActive), rt.bool(IsBigmapFull)

staticGetters.radar = function() return not IsRadarHidden() end
---@param on boolean
staticSetters.radar = function(on)
  if type(on) ~= "boolean" then error("Hud.radar: expected a boolean, got " .. tostring(on), 3) end
  DisplayRadar(on)
end

staticGetters.visible = function() return not IsHudHidden() end
---@param on boolean
staticSetters.visible = function(on)
  if type(on) ~= "boolean" then error("Hud.visible: expected a boolean, got " .. tostring(on), 3) end
  DisplayHud(on)
end

---@return "normal"|"expanded"|"full"
staticGetters.bigmap = function()
  if not IsBigmapActive() then return "normal" end
  return IsBigmapFull() and "full" or "expanded"
end
---@param mode "normal"|"expanded"|"full"
staticSetters.bigmap = function(mode)
  if mode ~= "normal" and mode ~= "expanded" and mode ~= "full" then
    error("Hud.bigmap: expected \"normal\", \"expanded\" or \"full\", got " .. tostring(mode), 3)
  end
  SetBigmapActive(mode ~= "normal", mode == "full")
end

---@type integer?
local radarZoom
staticGetters.radarZoom = function() return radarZoom end
---@param zoom integer
staticSetters.radarZoom = function(zoom)
  if math.type(zoom) ~= "integer" or zoom < 0 or zoom > 200 then error("Hud.radarZoom: expected an integer from 0 to 200", 3) end
  radarZoom = zoom
  SetRadarZoom(zoom)
end

